// Generated by crates/xtask from the Rust question model.
// Do not edit by hand; run ./build.sh (or cargo run -p xtask -- tsgen).

/**
 * A single authored parameter a generator reads.
 *
 * Parameters are declared rather than computed inline so a preview can show
 * an instructor the space a question draws from, and so the seed-vector
 * corpus can cover every branch of it.
 */
export type ParameterSpec =
  | {
      kind: "integerRange";
      low: number;
      high: number;
    }
  | {
      kind: "decimalRange";
      low: number;
      high: number;
      decimals: number;
    }
  | {
      kind: "choice";
      options: Array<string>;
    }
  | {
      kind: "fixed";
      value: string;
    };
